import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "resubmitting without replacing the rejected document is refused",
    { tag: "@LIF-04" },
    async ({ apiAs, factory }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const { vendor, extractions } = await factory.vendorInReview({ as: "member", name: uniqueName("Lifecycle") });
      const rejection = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      });
      await expectStatus(rejection, 200);

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      const body = await expectStatus<{ error: { code: string; missing_kinds: string[] } }>(response, 409);
      expect(body.error.code).toBe("documents_incomplete");
      expect(body.error.missing_kinds).toEqual(["w9"]);
    },
  );
});
